fragment:



            {gateway-app-id}
            api://{gateway-app-id}



                Gateway.Invoke










    <set-variable name="entraGroup" value="@{
        var jwt = (Jwt)context.Variables["entraToken"];
        string[] groups;
        if (!jwt.Claims.TryGetValue("groups", out groups)) { groups = new string[0]; }
        string best = "";
        int bestRank = int.MaxValue;
        foreach (var entry in "{{entra-gateway-groups}}".Split(';')) {
            var kv = entry.Split('=');
            if (kv.Length != 2) { continue; }
            var id = kv[0].Trim();
            var parts = kv[1].Split('|');
            int rank;
            if (parts.Length != 5 || !int.TryParse(parts[2], out rank)) { continue; }
            if (Array.IndexOf(groups, id) >= 0 && rank < bestRank) { best = id + "|" + kv[1].Trim(); bestRank = rank; }
        }
        return best;
    }" />





                application/json
                @((bool)context.Variables["entraOverage"] ? "entra-group-overage" : "entra-group")
                @(context.RequestId.ToString())
                @((string)context.Variables["caller"])
                @(new JObject(new JProperty("error", new JObject(
                    new JProperty("code", (bool)context.Variables["entraOverage"] ? "GroupsOverage" : "NoGatewayGroup"),
                    new JProperty("message", (bool)context.Variables["entraOverage"]
                        ? "The token has no groups claim because the caller is in too many groups. Use a workload identity or groupMembershipClaims ApplicationGroup."
                        : "The caller is not in any gateway security group, so no plan or budget applies.")))).ToString())














                application/json
                entra-mode-operation
                @(context.RequestId.ToString())

                @((string)context.Variables["budgetEpoch"])
                {"error":{"code":"OperationNotAvailable","message":"The Entra-only models API supports POST /chat/completions only."}}






{tier-branches}

    <set-variable name="requestedModel" value="@{
        var body = context.Request.Body?.As(preserveContent: true);
        return body?["model"]?.ToString() ?? "";
    }" />













                        application/json
                        model-denied
                        model-entitlement
                        @(context.RequestId.ToString())
                        @((string)context.Variables["entraTier"])
                        @((string)context.Variables["entraGroupName"])
                        @(new JObject(new JProperty("error", new JObject(
                            new JProperty("code", "ModelNotAllowed"),
                            new JProperty("message", "Model '" + (string)context.Variables["requestedModel"] + "' is not allowed for the '" + (string)context.Variables["entraTier"] + "' plan of group '" + (string)context.Variables["entraGroupName"] + "'. Allowed models: " + (string)context.Variables["entraAllowedModels"])))).ToString())









    <set-variable name="outputCapped" value="@{
        var body = context.Request.Body.As(preserveContent: true);
        var cap = (int)context.Variables["entraMaxOutputTokens"];
        foreach (var key in new [] { "max_completion_tokens", "max_tokens" }) {
            if (body[key] != null) { return (int)body[key] > cap; }
        }
        return false;
    }" />
    @{
        var body = context.Request.Body.As(preserveContent: true);
        var cap = (int)context.Variables["entraMaxOutputTokens"];
        body["model"] = (string)context.Variables["servedModel"];
        string key = body["max_completion_tokens"] != null ? "max_completion_tokens" : "max_tokens";
        if (body[key] == null || (int)body[key] > cap) { body[key] = cap; }
        return body.ToString();
    }






    <quota-by-key id="group-budget" calls="1000000" renewal-period="{budget-period-seconds}"
        counter-key="@("entra-group-" + (string)context.Variables["entraGroupId"] + "-" + (string)context.Variables["budgetEpoch"])"
        increment-condition="@(context.Response.StatusCode == 200)"
        increment-count="@{
            long cost = context.Variables.GetValueOrDefault("costMicroUsd", 0);
            long budget = (long)context.Variables["entraPoolMicroUsd"];
            return (int)Math.Min(int.MaxValue, (cost * 1000000L + budget - 1) / budget);
        }" />

    <quota-by-key id="member-budget" calls="1000000" renewal-period="{budget-period-seconds}"
        counter-key="@("entra-member-" + (string)context.Variables["entraOid"] + "-" + (string)context.Variables["budgetEpoch"])"
        increment-condition="@(context.Response.StatusCode == 200)"
        increment-count="@{
            long cost = context.Variables.GetValueOrDefault("costMicroUsd", 0);
            long budget = (long)context.Variables["entraMemberMicroUsd"];
            return (int)Math.Min(int.MaxValue, (cost * 1000000L + budget - 1) / budget);
        }" />
